package main

import (
	"fmt"
	"html/template"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"
)

// UserProfile represents a user's public profile
type UserProfile struct {
	Username    string
	Bio         string
	DisplayName string
	AvatarURL   string
}

// TemplateRenderer handles custom template rendering
type TemplateRenderer struct {
	templates map[string]*template.Template
}

func NewTemplateRenderer() *TemplateRenderer {
	return &TemplateRenderer{
		templates: make(map[string]*template.Template),
	}
}

// RenderUserGreeting renders a personalized greeting using user-supplied template
func (tr *TemplateRenderer) RenderUserGreeting(c *gin.Context) {
	username := c.Query("username")
	greetingTemplate := c.Query("greeting_tpl")

	if username == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "username required"})
		return
	}

	// Default greeting template if none provided
	if greetingTemplate == "" {
		greetingTemplate = "Hello, {{.Username}}! Welcome back."
	}

	// Basic sanitization - remove script tags (XSS protection)
	greetingTemplate = strings.ReplaceAll(greetingTemplate, "<script", "")
	greetingTemplate = strings.ReplaceAll(greetingTemplate, "</script>", "")

	profile := UserProfile{
		Username:    username,
		Bio:         "A regular user",
		DisplayName: username,
		AvatarURL:   fmt.Sprintf("/avatars/%s.png", username),
	}

	// Parse and execute the user-provided template
	tmpl, err := template.New("greeting").Parse(greetingTemplate)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid template syntax"})
		return
	}

	var result strings.Builder
	err = tmpl.Execute(&result, profile)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "template execution failed"})
		return
	}

	c.JSON(http.StatusOK, gin.H{
		"greeting": result.String(),
		"user":     profile.Username,
	})
}

// RenderNotification renders notification with user-controlled format
func (tr *TemplateRenderer) RenderNotification(c *gin.Context) {
	messageFormat := c.PostForm("format")
	notifData := c.PostForm("data")

	if messageFormat == "" {
		messageFormat = "Notification: {{.}}"
	}

	tmpl, err := template.New("notif").Parse(messageFormat)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "bad format"})
		return
	}

	var result strings.Builder
	err = tmpl.Execute(&result, notifData)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "render failed"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"notification": result.String()})
}

func main() {
	r := gin.Default()

	renderer := NewTemplateRenderer()

	// Public API routes
	api := r.Group("/api/v1")
	{
		api.GET("/greeting", renderer.RenderUserGreeting)
		api.POST("/notification", renderer.RenderNotification)
	}

	// Health check
	r.GET("/health", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "ok"})
	})

	r.Run(":8080")
}
